using Test
using FinancialCalibrator
using FinancialMonteCarlo
using FinancialFFT
using FinancialToolbox
using Optim
using Dates
using ForwardDiff
using LinearAlgebra
using Zygote
using Mooncake
using Enzyme
using ADTypes: AutoForwardDiff, AutoMooncake, AutoEnzyme, AutoZygote
import DifferentiationInterface as DI

const FC = FinancialCalibrator

# Synthetic market: implied vols are generated by `true_model` priced with `method`.
function synthetic_market(true_model, method; S0 = 100.0, r = 0.01, d = 0.0, T = [0.5, 1.0, 2.0], strikes = collect(80.0:10.0:120.0))
    p = FinancialMonteCarlo.get_parameters(true_model)
    vols = reduce(vcat, [blsimpv.(S0, strikes, r, t, smile_prices(true_model, method, p, strikes, r, t), d)' for t in T])
    dates = [Date(2020, 1, 1) + Day(round(Int, 365 * t)) for t in T]
    return MarketData(T, dates, fill(r, length(T)), strikes, vols)
end

@testset "Models and methods" begin
    progress("Models and methods")
    und, mkt = adapter(retriever(CalibrationID("Dax", "22Aug2016", "EUR"), IOFileInputStrategy()))
    idx = 3
    prices(model, method) = smile_prices(model, method, FinancialMonteCarlo.get_parameters(model), mkt.Strikes, mkt.ZeroRates[idx], mkt.TimeToMaturity[idx])

    levy_models = ("BlackScholes" => BlackScholesProcess(0.2, und), "Merton" => MertonProcess(0.2, 0.5, -0.1, 0.2, und), "Kou" => KouProcess(0.2, 0.5, 0.4, 10.0, 15.0, und), "VarianceGamma" => VarianceGammaProcess(0.2, -0.03, 0.16, und), "NIG" => NormalInverseGaussianProcess(0.2, -0.03, 0.16, und))
    methods = ("CarrMadan" => CarrMadanMethod(400.0, 14), "CarrMadanLewis" => CarrMadanLewisMethod(400.0, 14), "Lewis" => LewisMethod(100.0, 4001), "Cos" => CosMethod(1024))

    @testset "$mname" for (mname, model) in levy_models
        progress("$mname")
        ref = prices(model, last(methods[2]))
        @test all(isfinite, ref)
        @test all(>(0), ref)
        @testset "$ename" for (ename, method) in methods
            progress("$mname / $ename")
            pr = prices(model, method)
            @test length(pr) == length(mkt.Strikes)
            @test all(isfinite, pr)
            @test isapprox(pr, ref; rtol = 1e-3, atol = 0.05)
            loss = FC.loss(FinancialMonteCarlo.get_parameters(model), model, method, mkt)
            @test loss < 1e4
        end
    end

    @testset "Heston" begin
        progress("Heston")
        model = HestonProcess(0.3, 0.2, 0.0, 1.5, -0.5, 0.04, und)
        pr_cm = prices(model, CarrMadanMethod(400.0, 14))
        pr_cml = prices(model, CarrMadanLewisMethod(400.0, 14))
        @test all(isfinite, pr_cm)
        @test isapprox(pr_cm, pr_cml; rtol = 1e-3, atol = 0.05)
        @test FC.loss(FinancialMonteCarlo.get_parameters(model), model, CarrMadanMethod(400.0, 14), mkt) < 1e4
    end

    @testset "Calibration recovers a synthetic surface" begin
        progress("Calibration recovers a synthetic surface")
        und0 = FinancialMonteCarlo.Underlying(100.0)
        cm = CarrMadanMethod(400.0, 14)

        @testset "BlackScholes / $name" for (name, method) in ("CarrMadan" => cm, "Cos" => CosMethod(1024), "Lewis" => LewisMethod(100.0, 4001))
            progress("BlackScholes / $name")
            smkt = synthetic_market(BlackScholesProcess(0.2, und0), method)
            start = BlackScholesProcess(0.35, und0)
            res = calibrate(start, method, smkt)
            @test res.OptimalValue < 1e-3
            @test res.OptimalParam[1] ≈ 0.2 atol = 1e-2
            @test size(res.ModelVolatility) == size(smkt.Volatility)
            @test isapprox(res.ModelVolatility, smkt.Volatility; atol = 5e-3)
        end

        @testset "VarianceGamma / CarrMadan" begin
            progress("VarianceGamma / CarrMadan")
            smkt = synthetic_market(VarianceGammaProcess(0.2, -0.1, 0.2, und0), cm)
            start = VarianceGammaProcess(0.25, -0.05, 0.3, und0)
            loss0 = FC.loss(FinancialMonteCarlo.get_parameters(start), start, cm, smkt)
            res = calibrate(start, cm, smkt)
            @test res.OptimalValue < loss0 / 10
        end

        @testset "Optimizer options" begin
            progress("Optimizer options")
            smkt = synthetic_market(VarianceGammaProcess(0.2, -0.1, 0.2, und0), cm)
            start = VarianceGammaProcess(0.25, -0.05, 0.3, und0)
            loss0 = FC.loss(FinancialMonteCarlo.get_parameters(start), start, cm, smkt)
            # without the Levenberg–Marquardt polish, which would take both to the minimum
            short = calibrate(start, cm, smkt, NelderMead(), Optim.Options(iterations = 2); polish = false)
            full = calibrate(start, cm, smkt, NelderMead(), Optim.Options(iterations = 100); polish = false)
            @test short.OptimalValue <= loss0
            @test full.OptimalValue < short.OptimalValue
        end

        # The calibration ends where the gradient of the loss vanishes, and calibrated_parameters differentiates it with
        # respect to the quotes by the implicit function theorem: against central differences of recalibrations, and the
        # whole Jacobian against the formula ∂p*/∂v = -H⁻¹ ∂ᵥ∇ₚL. Lewis for VG: the Cos derivatives of FinancialFFT are not
        # those of its values where its series converges slowly (the truncation range is held constant).
        @testset "Stationary and differentiable in the quotes / $name" for (name, truth, start, method) in (("BlackScholes", BlackScholesProcess(0.2, und0), BlackScholesProcess(0.3, und0), CosMethod(1024)), ("VarianceGamma", VarianceGammaProcess(0.2, -0.1, 0.2, und0), VarianceGammaProcess(0.25, -0.05, 0.3, und0), LewisMethod(100.0, 4001)))
            progress("Stationary and differentiable in the quotes / $name")
            exact = synthetic_market(truth, method)
            # quotes that no model of the family fits exactly
            smkt = MarketData(exact.TimeToMaturity, exact.MaturityDates, exact.ZeroRates, exact.Strikes, exact.Volatility .* (1 .+ 0.01 .* sin.(reshape(1:length(exact.Volatility), size(exact.Volatility)))))
            cache = FC.loss_cache(start, method, smkt)
            L(p, vols) = sum(abs2, vol_errors(p, start, method, smkt, cache; vols = vols)) / 2
            res = calibrate(start, method, smkt)
            p = res.OptimalParam
            @test res.OptimalValue ≈ L(p, smkt.Volatility)
            @test norm(ForwardDiff.gradient(q -> L(q, smkt.Volatility), p)) < 1e-9
            sz = size(smkt.Volatility)
            J = ForwardDiff.jacobian(v -> calibrated_parameters(start, method, smkt, reshape(v, sz)), vec(smkt.Volatility))
            H = ForwardDiff.hessian(q -> L(q, smkt.Volatility), p)
            ∂g_∂v = ForwardDiff.jacobian(v -> ForwardDiff.gradient(q -> L(q, reshape(v, sz)), p), vec(smkt.Volatility))
            @test J ≈ -(H \ ∂g_∂v) rtol = 1e-10
            # reverse mode from outside, through the ChainRules rule of ImplicitDifferentiation
            w = collect(1.0:length(p))
            @test vec(Zygote.gradient(v -> dot(w, calibrated_parameters(start, method, smkt, v)), smkt.Volatility)[1]) ≈ transpose(J) * w rtol = 1e-10
            # a lazy cotangent (sum): ImplicitDifferentiation must not insist on the type it prepared the pullback with
            @test vec(Zygote.gradient(v -> sum(calibrated_parameters(start, method, smkt, v)), smkt.Volatility)[1]) ≈ vec(sum(J; dims = 1)) rtol = 1e-10
            # Mooncake from outside (the rule of the extension), and Mooncake for the quotes inside the implicit function
            mc = AutoMooncake(; config = nothing)
            @test vec(DI.gradient(v -> dot(w, calibrated_parameters(start, method, smkt, v)), mc, smkt.Volatility)) ≈ transpose(J) * w rtol = 1e-10
            @test vec(DI.gradient(v -> dot(w, calibrated_parameters(start, method, smkt, v; implicit_backends = (x = mc, y = AutoForwardDiff()))), mc, smkt.Volatility)) ≈ transpose(J) * w rtol = 1e-10
            # Enzyme, through the rules of the extension, which apply ImplicitDifferentiation's Enzyme rules
            enzyme(mode) = AutoEnzyme(; mode = Enzyme.set_runtime_activity(mode), function_annotation = Enzyme.Const)
            @test vec(DI.gradient(v -> dot(w, calibrated_parameters(start, method, smkt, v)), enzyme(Enzyme.Reverse), smkt.Volatility)) ≈ transpose(J) * w rtol = 1e-10
            if name == "BlackScholes"
                @test vec(DI.gradient(v -> dot(w, calibrated_parameters(start, method, smkt, v)), enzyme(Enzyme.Forward), smkt.Volatility)) ≈ transpose(J) * w rtol = 1e-10
            end
            i = LinearIndices(sz)[2, 3]
            recalibrate(h) = calibrated_parameters(start, method, smkt, reshape(vec(smkt.Volatility) .+ h .* (1:prod(sz) .== i), sz))
            h = 1e-4
            @test J[:, i] ≈ (recalibrate(h) - recalibrate(-h)) / 2h rtol = 1e-3
        end

        @testset "Shifted LogNormalMixture / Analytic" begin
            progress("Shifted LogNormalMixture / Analytic")
            true_model = ShiftedProcess(LogNormalMixture((0.15, 0.3), (0.5,), und0), -0.1)
            smkt = synthetic_market(true_model, AnalyticMethod())
            start = ShiftedProcess(LogNormalMixture((0.2, 0.25), (0.4,), und0), -0.05)
            loss0 = FC.loss(FinancialMonteCarlo.get_parameters(start), start, AnalyticMethod(), smkt)
            res = calibrate(start, AnalyticMethod(), smkt)
            @test res.OptimalValue < loss0 / 10
        end
    end

    # Zygote and Mooncake differentiate the loss through rules that run its try themselves (#40): a zero gradient where
    # it is Inf, and as autodiff of calibrate, whose LBFGS line search reaches parameters that cannot be priced on DAX.
    # The degenerate DAX optimum of the mixture (the Bachelier limit) leaves each backend at its own local minimum, which
    # differs between machines (on Linux CI Zygote and Mooncake ended above ForwardDiff): on DAX only a finite loss is
    # checked, and the convergence on quotes generated by a known mixture, whose optimum is unique (#41).
    @testset "Reverse backends through the try of the loss (#40)" begin
        progress("Reverse backends through the try of the loss (#40)")
        bs = BlackScholesProcess(0.2, und)
        model = ShiftedProcess(LogNormalMixture((0.2, 0.35), (0.5,), und), 0.05)
        cache = FC.loss_cache(model, AnalyticMethod(), mkt)
        p = FinancialMonteCarlo.get_parameters(model)
        mixture_loss(x) = FC.loss(x, model, AnalyticMethod(), mkt, cache)
        bs_loss(x) = FC.loss(x, bs, AnalyticMethod(), mkt)
        reference = ForwardDiff.gradient(mixture_loss, p)
        # quotes of a known mixture on the DAX strikes and maturities
        truth = ShiftedProcess(LogNormalMixture((0.15, 0.3), (0.6,), und), 0.1)
        smkt = let c = FC.loss_cache(truth, AnalyticMethod(), mkt), v = copy(mkt.Volatility)
            v[c.flat.positions] .= FC.vol_errors(FinancialMonteCarlo.get_parameters(truth), truth, AnalyticMethod(), mkt, c; vols = zero(v))
            MarketData(mkt.TimeToMaturity, mkt.MaturityDates, mkt.ZeroRates, mkt.Strikes, v)
        end
        @testset "$(nameof(typeof(backend)))" for backend in (AutoZygote(), AutoMooncake(; config = nothing))
            progress("Reverse backends through the try of the loss / $(nameof(typeof(backend)))")
            @test DI.gradient(mixture_loss, backend, p) ≈ reference rtol = 1e-12
            @test DI.value_and_gradient(bs_loss, backend, [-0.2]) == (Inf, [0.0])
            @test_throws MethodError DI.gradient(x -> FC.loss(x, bs, NoPricer(), mkt), backend, [0.2])
            @test isfinite(calibrate(model, AnalyticMethod(), mkt, LBFGS(); autodiff = backend).OptimalValue)
            synthetic = calibrate(model, AnalyticMethod(), smkt, LBFGS(); autodiff = backend)
            @test synthetic.OptimalValue < 1e-20
            @test synthetic.OptimalParam ≈ FinancialMonteCarlo.get_parameters(truth) rtol = 1e-8
        end
    end
end
